.__UIV_SCOPE__ .switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 3.5em;
  height: 2em;
}

.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #333;
  transition: 0.4s;
  border-radius: 30px;
  overflow: hidden;
}

.__UIV_SCOPE__ .circle {
  position: absolute;
  content: "";
  height: 1.4em;
  width: 1.4em;
  border-radius: 20px;
  left: 0.3em;
  bottom: 0.3em;
  background-color: #fff000;
  transform: rotate(360deg) translateX(0);
  transition: 0.4s;
}

.__UIV_SCOPE__ .switch input:checked + .slider .circle {
  transform: rotate(0deg) translateX(1.5em) !important;
}

.__UIV_SCOPE__ .switch input:checked + .slider .circle .shine {
  transform: translate(0%, 0%) !important;
}

.__UIV_SCOPE__ .switch input:checked + .slider .circle .moon {
  left: -10%;
  opacity: 1;
  transform: translateY(-60%);
}

.__UIV_SCOPE__ .moon {
  position: absolute;
  left: -100%;
  top: 50%;
  opacity: 0;
  background-color: #333;
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 99999px;
  transform: translateY(-50%);
  transition: all 0.4s;
}

.__UIV_SCOPE__ .shine {
  display: block;
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0.25rem;
  height: 0.25rem;
  background-color: #fff000;
  border-radius: 1rem;
  transition: all 0.4s;
}

.__UIV_SCOPE__ .shine-1 {
  transform: translate(-50%, -375%);
}
.__UIV_SCOPE__ .shine-2 {
  transform: translate(175%, -275%);
}
.__UIV_SCOPE__ .shine-3 {
  transform: translate(275%, -50%);
}
.__UIV_SCOPE__ .shine-4 {
  transform: translate(175%, 175%);
}
.__UIV_SCOPE__ .shine-5 {
  transform: translate(-50%, 275%);
}
.__UIV_SCOPE__ .shine-6 {
  transform: translate(-275%, 175%);
}
.__UIV_SCOPE__ .shine-7 {
  transform: translate(-375%, -50%);
}
.__UIV_SCOPE__ .shine-8 {
  transform: translate(-275%, -275%);
}
